// === CONFIG LA PULPE: carpetas y ajustes técnicos ===
const CONFIG = {
  // Los datos del negocio (nombre, teléfono, Instagram, hashtags, logo) NO van acá:
  // están en datos-negocio.json y lapulpe.png, en la carpeta Recursos de Drive.
  cliente_id: 'la-pulpe',
  email_aviso: 'COMPLETAR@mail.com',      // a quién le avisamos que hay reel listo
  carpeta_reels_id: 'COMPLETAR_ID_CARPETA_LISTOS_REELS',
  carpeta_historias_id: 'COMPLETAR_ID_CARPETA_LISTOS_HISTORIAS',
  carpeta_feed_id: 'COMPLETAR_ID_CARPETA_LISTOS_FEED',
  carpeta_edicion_id: 'COMPLETAR_ID_CARPETA_EDICION',   // acá va el crudo ya procesado
  datos_negocio_id: 'COMPLETAR_ID_ARCHIVO_DATOS_NEGOCIO_JSON',
  logo_id: 'COMPLETAR_ID_ARCHIVO_LOGO_PNG',
  fuente_id: 'COMPLETAR_ID_ARCHIVO_FUENTE_TTF',
  duracion_max_seg: 90,      // reel
  historia_max_seg: 15,      // historia
  subs_palabras_por_bloque: 4,
  subs_mayusculas: true,
  tamano_max_mb: 500,
};

const salida = [];
for (const item of $input.all()) {
  const f = item.json;
  const mime = f.mimeType || '';
  const mb = Number(f.size || 0) / 1024 / 1024;
  if (!mime.startsWith('video/')) continue;          // solo videos
  if (mb > CONFIG.tamano_max_mb) continue;           // evita archivos gigantes
  const ext = (String(f.name || '').match(/\.[a-zA-Z0-9]+$/) || ['.mp4'])[0].toLowerCase();
  salida.push({ json: {
    ...CONFIG,
    file_id: f.id,
    file_name: f.name,
    dir: `/home/node/.n8n-files/lapulpe/${f.id}`,
    crudo: `/home/node/.n8n-files/lapulpe/${f.id}/crudo${ext}`,
    fecha: new Date().toISOString().slice(0, 10),
  }});
}
return salida;   // si no hay videos, el flujo se detiene acá

// === Datos del negocio: se leen de datos-negocio.json (Drive) en cada video ===
// Para cambiar teléfono, Instagram, hashtags, etc., se edita ese archivo, no n8n.
const salida = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  let d;
  try { d = JSON.parse(buf.toString('utf8').replace(/^﻿/, '')); }
  catch (e) { throw new Error('datos-negocio.json tiene un error de formato (revisá comas y comillas): ' + e.message); }
  if (!d.nombre) throw new Error('Falta "nombre" en datos-negocio.json');
  d.hashtags_base = Array.isArray(d.hashtags_base) ? d.hashtags_base : [];
  // Pie fijo del caption: lo agregamos nosotros, no Claude, para que el teléfono nunca salga mal
  d.pie_caption = [
    d.telefono_reservas ? `📞 Reservas: ${d.telefono_reservas}` : '',
    d.direccion ? `📍 ${d.direccion}` : '',
    d.horario ? `🕛 ${d.horario}` : '',
  ].filter(Boolean).join('\n');
  const hex = (c, def) => (/^#?[0-9a-fA-F]{6}$/.test(String(c || '')) ? String(c).replace('#', '') : def);
  d.ff_marco = '0x' + hex(d.color_marco, 'F3EBDD');   // formato de color para FFmpeg
  d.ff_texto = '0x' + hex(d.color_texto, '1A1A1A');
  salida.push({ json: d, pairedItem: { item: i } });
}
return salida;

// === Code node "Armar subtítulos" (n8n) ===
const cfg = $('Config La Pulpe').item.json;
const r = $input.item.json;            // respuesta de Groq (verbose_json)
const texto = (r.text || '').trim();

function ts(s) {
  const ms = Math.max(0, Math.round(s * 1000));
  const h = String(Math.floor(ms / 3600000)).padStart(2, '0');
  const m = String(Math.floor(ms / 60000) % 60).padStart(2, '0');
  const sec = String(Math.floor(ms / 1000) % 60).padStart(2, '0');
  const mil = String(ms % 1000).padStart(3, '0');
  return `${h}:${m}:${sec},${mil}`;
}

// Bloques cortos para reel: hasta N palabras o ~1,8 s por bloque
const MAX_PALABRAS = cfg.subs_palabras_por_bloque || 4;
const MAX_SEG = 1.8;
const bloques = [];
const words = Array.isArray(r.words) ? r.words : [];
if (words.length) {
  let act = null;
  for (const w of words) {
    const palabra = String(w.word || '').trim();
    if (!palabra) continue;
    if (!act || act.n >= MAX_PALABRAS || (w.end - act.start) > MAX_SEG) {
      if (act) bloques.push(act);
      act = { start: w.start, end: w.end, text: palabra, n: 1 };
    } else {
      act.end = w.end; act.text += ' ' + palabra; act.n++;
    }
  }
  if (act) bloques.push(act);
} else if (Array.isArray(r.segments)) {
  for (const s of r.segments) {
    const t = String(s.text || '').trim();
    if (t) bloques.push({ start: s.start, end: s.end, text: t });
  }
}

const srt = bloques
  .map((b, i) => `${i + 1}\n${ts(b.start)} --> ${ts(b.end)}\n${cfg.subs_mayusculas ? b.text.toUpperCase() : b.text}\n`)
  .join('\n');

return {
  json: { transcripcion: texto, tiene_subs: bloques.length > 0, cant_bloques: bloques.length },
  binary: {
    data: {
      data: Buffer.from(srt || '1\n00:00:00,000 --> 00:00:00,500\n \n', 'utf8').toString('base64'),
      mimeType: 'application/x-subrip',
      fileName: 'subs.srt',
    },
  },
};

