={{ (() => {
  const c = $('Config La Pulpe').item.json;
  const d = $('Datos del negocio').item.json;
  const r = $('Leer respuesta de Claude').item.json;
  const subs = $('Armar subtítulos').item.json.tiene_subs;
  const estilo = "FontName=DejaVu Serif,FontSize=15,Bold=1,PrimaryColour=&H00FFFFFF,OutlineColour=&H00000000,BorderStyle=1,Outline=2,Shadow=0,Alignment=2,MarginV=70";
  const sub = subs ? `,subtitles=${c.dir}/subs.srt:fontsdir=${c.dir}:force_style='${estilo}'` : '';
  const font = `fontfile=${c.dir}/fuente.ttf:expansion=none`;
  const txt = (nombre, b64) => `printf '%s' '${b64}' | base64 -d > "${c.dir}/${nombre}.txt" && `;
  // REEL 9:16: video entero, subtítulos, marco fino del color de marca y logo arriba a la derecha
  const logo = d.logo_en_reel !== false;
  const ancho = Number(d.logo_ancho_px) || 200;
  const opac = Math.min(1, Math.max(0.1, Number(d.logo_opacidad) || 0.9));
  const base = `scale=1080:1920:force_original_aspect_ratio=increase,crop=1080:1920,setsar=1${sub},drawbox=x=0:y=0:w=iw:h=ih:color=${d.ff_marco}:t=14`;
  const fc = logo
    ? `[0:v]${base}[v];[1:v]scale=${ancho}:-1,format=rgba,colorchannelmixer=aa=${opac}[lg];[v][lg]overlay=W-w-48:220:format=auto,format=yuv420p[out]`
    : `[0:v]${base},format=yuv420p[out]`;
  return `ffmpeg -hide_banner -loglevel error -y -i "${c.crudo}"` + (logo ? ` -i "${c.dir}/logo.png"` : '') +
    ` -t ${c.duracion_max_seg} -filter_complex "${fc}" -map "[out]" -map 0:a? -af loudnorm=I=-14:TP=-1.5:LRA=11 -c:a aac -b:a 128k -ar 48000 -c:v libx264 -preset veryfast -crf 23 -movflags +faststart "${c.dir}/reel.mp4"`;
})() }}

